const APPS_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbwvEgWZBa1JT5zgSiYg3rQTDCYHOfdiSEyzyNcSZM03fX1zE3_e9E28JUClPHVOp9D_CA/exec";

// Left-panel photo per course, keyed by course_id
const PANEL_IMAGES = {
  "ai-agentic-engineering": "",
  "llmops-engineering-bootcamp": "",
  "cv-engineering-defencetech": "",
  "ai-qa-engineering": "",
  "ai-quality-engineering": ""
};

const T = {
  ENG: {
    confirms: "This certificate confirms that,",
    verified: "Verified", partial: "Attendance confirmed",
    duration: "Duration", format: "Format", capstone: "Capstone-project:",
    certNum: "certificate number", issued: "issued", code: "verification code",
    topicsTitle: "Program topics",
    disclaimer1: "This page is an official confirmation of course completion issued by Neoversity.",
    disclaimer2: "Questions about certificate validity \u2014",
    notFoundTitle: "Certificate not found",
    downloadBtn: "Download PDF",
    topicsSub: (n) => n + " modules covered",
  },
  UKR: {
    confirms: "цей сертифікат підтверджує, що",
    verified: "Верифіковано", partial: "Підтверджено відвідування",
    duration: "Тривалість", format: "Формат", capstone: "Capstone-проєкт:",
    certNum: "номер сертифіката", issued: "видано", code: "код верифікації",
    topicsTitle: "Теми програми",
    disclaimer1: "Ця сторінка є офіційним підтвердженням проходження курсу видавцем Neoversity.",
    disclaimer2: "Питання щодо дійсності сертифіката \u2014",
    notFoundTitle: "Сертифікат не знайдено",
    downloadBtn: "Завантажити PDF",
    topicsSub: (n) => n + " модулів",
  }
};

function esc(s) {
  return String(s == null ? "" : s).replace(/[&<>"']/g, (c) => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
}

function nl2br(s) {
  return esc(s).replace(/\n/g, "<br>");
}

function topicCardsHtml(topics) {
  return topics.map(([num, title, tags]) => `
    <div class="topic-card">
      <div class="topic-head"><div class="topic-title">${esc(title)}</div><div class="topic-num">${esc(num)}</div></div>
      <div class="topic-tags">${tags.map(t => `<span class="tag">${esc(t)}</span>`).join("")}</div>
    </div>`).join("\n");
}

